        return []
    n = len(coords)
    if n <= 1:
        return []

    try:
        if depot.__class__ in (list, tuple):
            depot = depot[0] if depot else 0
    except:
        pass
    depot = int(depot)

    if demands is None:
        demands = [0] * n
    if capacity is None:
        capacity = 0

    def xy(i):
        p = coords[i]
        return p[0], p[1]

    def dist(i, j):
        ax, ay = xy(i)
        bx, by = xy(j)
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    customers = []
    i = 0
    while i < n:
        if i != depot:
            customers.append(i)
        i += 1

    unrouted = {}
    for c in customers:
        unrouted[c] = 1

    def route_cost(route):
        if not route:
            return 0.0
        c = dist(depot, route[0]) + dist(route[-1], depot)
        k = 0
        while k + 1 < len(route):
            c += dist(route[k], route[k + 1])
            k += 1
        return c

    def route_load(route):
        s = 0
        for c in route:
            s += demands[c]
        return s

    def insert_cost(route, pos, cust):
        a = depot if pos == 0 else route[pos - 1]
        b = depot if pos == len(route) else route[pos]
        return dist(a, cust) + dist(cust, b) - dist(a, b)

    routes = []

    # Greedy construction: seed by farthest/high-demand customers, then best insertion
    while unrouted:
        start = None
        best_key = None
        for c in unrouted:
            d = demands[c]
            if capacity > 0 and d > capacity:
                continue
            key = (-d, -dist(depot, c), c)
            if best_key is None or key < best_key:
                best_key = key
                start = c
        if start is None:
            for c in unrouted:
                key = (-dist(depot, c), c)
                if best_key is None or key < best_key:
                    best_key = key
                    start = c

        route = [start]
        del unrouted[start]
        load = demands[start]

        while unrouted:
            best = None
            best_c = None
            best_p = None
            for c in unrouted:
                d = demands[c]
                if capacity > 0 and load + d > capacity:
                    continue
                pos = 0
                while pos <= len(route):
                    ic = insert_cost(route, pos, c)
                    a = depot if pos == 0 else route[pos - 1]
                    b = depot if pos == len(route) else route[pos]
                    key = (ic, dist(a, c) + dist(c, b), dist(depot, c), d, c, pos)
                    if best is None or key < best:
                        best = key
                        best_c = c
                        best_p = pos
                    pos += 1
            if best_c is None:
                break
            route.insert(best_p, best_c)
            del unrouted[best_c]
            load += demands[best_c]

        routes.append(route)

    # Repair: if capacity was too tight or data odd, create singleton routes for leftovers
    if unrouted:
        for c in list(unrouted.keys()):
            routes.append([c])
            del unrouted[c]

    # Local search: intra-route 2-opt
    improved = True
    while improved:
        improved = False
        r = 0
        while r < len(routes):
            route = routes[r]
            m = len(route)
            if m >= 4:
                best_delta = 0.0
                bi = -1
                bj = -1
                i = 0
                while i < m - 1:
                    a = depot if i == 0 else route[i - 1]
                    b = route[i]
                    j = i + 2
                    while j < m:
                        c = route[j - 1]
                        d = depot if j == m else route[j]
                        delta = (dist(a, c) + dist(b, d)) - (dist(a, b) + dist(c, d))
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            bi = i
                            bj = j
                        j += 1
                    i += 1
                if bi >= 0:
                    route[bi:bj] = route[bi:bj][::-1]
                    improved = True
            r += 1

        # Inter-route relocate
        if not improved:
            best_delta = 0.0
            move = None
            i = 0
            while i < len(routes):
                ra = routes[i]
                if len(ra) != 0:
                    j = 0
                    while j < len(ra):
                        c = ra[j]
                        dc = demands[c]
                        prev = depot if j == 0 else ra[j - 1]
                        nxt = depot if j == len(ra) - 1 else ra[j + 1]
                        remove_gain = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                        k = 0
                        while k < len(routes):
                            if k != i:
                                rb = routes[k]
                                lb = route_load(rb)
                                if capacity <= 0 or lb + dc <= capacity:
                                    p = 0
                                    while p <= len(rb):
                                        a = depot if p == 0 else rb[p - 1]
                                        b = depot if p == len(rb) else rb[p]
                                        add_cost = dist(a, c) + dist(c, b) - dist(a, b)
                                        delta = add_cost - remove_gain
                                        key = (delta, len(rb), i, j, k, p, c)
                                        if delta < best_delta - 1e-12:
                                            best_delta = delta
                                            move = (i, j, k, p)
                                        p += 1
                            k += 1
                        j += 1
                i += 1

            if move is not None:
                i, j, k, p = move
                c = routes[i][j]
                routes[i].pop(j)
                if i < k:
                    k -= 1
                routes[k].insert(p, c)
                if len(routes[i]) == 0:
                    routes.pop(i)
                improved = True

        # Inter-route swap
        if not improved:
            best_delta = 0.0
            swap = None
            i = 0
            while i < len(routes):
                ra = routes[i]
                la = route_load(ra)
                j = i + 1
                while j < len(routes):
                    rb = routes[j]
                    lb = route_load(rb)
                    a_idx = 0
                    while a_idx < len(ra):
                        ca = ra[a_idx]
                        da = demands[ca]
                        prev_a = depot if a_idx == 0 else ra[a_idx - 1]
                        next_a = depot if a_idx == len(ra) - 1 else ra[a_idx + 1]
                        rem_a = dist(prev_a, ca) + dist(ca, next_a) - dist(prev_a, next_a)
                        b_idx = 0
                        while b_idx < len(rb):
                            cb = rb[b_idx]
                            db = demands[cb]
                            if capacity <= 0 or (la - da + db <= capacity and lb - db + da <= capacity):
                                prev_b = depot if b_idx == 0 else rb[b_idx - 1]
                                next_b = depot if b_idx == len(rb) - 1 else rb[b_idx + 1]
                                rem_b = dist(prev_b, cb) + dist(cb, next_b) - dist(prev_b, next_b)
                                add_a = dist(prev_a, cb) + dist(cb, next_a) - dist(prev_a, next_a)
                                add_b = dist(prev_b, ca) + dist(ca, next_b) - dist(prev_b, next_b)
                                delta = (add_a + add_b) - (rem_a + rem_b)
                                if delta < best_delta - 1e-12:
                                    best_delta = delta
                                    swap = (i, a_idx, j, b_idx)
                            b_idx += 1
                        a_idx += 1
                    j += 1
                i += 1

            if swap is not None:
                i, ai, j, bj = swap
                routes[i][ai], routes[j][bj] = routes[j][bj], routes[i][ai]
                improved = True

    # Final clean-up: remove empty routes
    final_routes = []
    for r in routes:
        if len(r) > 0:
            final_routes.append(r)
    return final_routes
